mapper.select:
SELECT u.organization_uuid AS organization_uuid,
    w.uuid AS workspace_uuid, w.external_id AS workspace_external_id,
    u.uuid AS user_uuid, u.external_id AS user_external_id
FROM users u
JOIN LATERAL (
    SELECT uuid, external_id FROM workspaces
    WHERE organization_uuid = u.organization_uuid AND archived_at IS NULL
    ORDER BY CASE WHEN external_id = 'workspace_default' THEN 0 ELSE 1 END,
        created_at ASC, uuid ASC
    LIMIT 1
) w ON TRUE
WHERE u.organization_uuid = #{organizationUUID}
AND u.deleted_at IS NULL
AND (
    u.external_id = #{userID}
    OR u.uuid = #{userUUID}
    OR 'user_' || LEFT(REPLACE(CAST(u.uuid AS text), '-', ''), 24) = #{userID}
)
LIMIT 1
